<?phpif (!defined('BASEPATH'))    exit('No direct script access allowed');class mdyeintypemodel extends CI_Model {    function fnGetDyeingTypeInfo($VarTypeName='',$VarStatus='',$VarId='') {        $this->db->select('id,dyeingname,updatedby,status,datecreated,dateupdated'); // Select field        $this->db->from(KN_MASTER_DYEING_TYPE);        if($VarStatus<>'') {            $this->db->where_in('status',array($VarStatus));        } else {            $this->db->where_in('status',array(1,2));        }        if($VarId<>'') {            $ArrWhere['id'] 				= $VarId;        }        if($VarTypeName<>'') {            $ArrWhere['dyeingname'] 		= $VarTypeName;        }        if(@count($ArrWhere)>=1) {            $this->db->where($ArrWhere);        }        $ArrResultList	    	    		= $this->db->get()->result_array();        return $ArrResultList;    }    function fnCheckDyeingType($VarTypeName='',$VarId='') {        $this->db->select('id,dyeingname,updatedby,status,datecreated,dateupdated');        $this->db->from(KN_MASTER_DYEING_TYPE);        $ArrWhere = array('status'=>"1");        if($VarId<>'') {            $this->db->where_not_in('id',array($VarId));        }        if($VarTypeName<>'') {            $ArrWhere['dyeingname']		= $VarTypeName;        }        $this->db->where($ArrWhere);        $ObjResult  					= $this->db->get();        $ArrResultList					= $ObjResult->result_array();        return $ArrResultList;    }    function saveDyeingTypeInfo($ArrUpdateData){        $VarId                                                  = $ArrUpdateData['id'];        if($VarId=="") {            $ArrCheckExist			       					    = $this->fnGetDyeingTypeInfo($ArrUpdateData['dyeingname'],1);            if(@$ArrCheckExist['id']=='' && @$ArrCheckExist['id']==0) {                unset($ArrUpdateData['id']);                $this->db->insert(KN_MASTER_DYEING_TYPE,$ArrUpdateData);                $VarId                                          = $this->db->insert_id();                $ArrResult['errcode']						    = 1;                $ArrResult['msg']							    = '';                $ArrResult['id']							    = $VarId;                $ArrResult['eid']							    = urlencode(base64_encode($VarId));            } else {                $ArrResult['errcode']							= '-1';                $ArrResult['msg']								= "This Type name already exists!!";            }        } else {            $ArrCheckExist									    = $this->fnCheckDyeingType($ArrUpdateData['dyeingname'],$VarId);            if(@$ArrCheckExist['id']=='' && $ArrUpdateData['dyeingname']<>'') {                if($this->db->update(KN_MASTER_DYEING_TYPE,$ArrUpdateData,array('id'=>$VarId))) {                    $ArrResult['errcode']					    = 1;                    $ArrResult['msg']							= '';                    $ArrResult['id']							= $VarId;                    $ArrResult['eid']							= urlencode(base64_encode($VarId));                } else {                    $ArrResult['errcode']						= '-1';                    $ArrResult['msg']							= 'Invalid Data!';                }            }  else {                $ArrResult['errcode']						    = '-1';                $ArrResult['msg']							    = "This dyeing Type has already Exist!";            }        }        return $ArrResult;    }    function fnCountDyeingType($VarTypeName='',$VarStatus='',$VarAlphaFilter=''){        $ArrUserLoggedInfo = fnGetUserLoggedInfo('1');        $ArrWhere                   = array();        if($VarTypeName<>'') {            $ArrWhere[]             = "d.dyeingname like '%".$VarTypeName."%'";        }        if($VarAlphaFilter <> '') {            $ArrWhere[]             = "d.dyeingname like '".$VarAlphaFilter."%'";        }        if($VarStatus<>'') {            $ArrWhere[]             = "d.status=".$VarStatus;        } else {            $ArrWhere[]             = "d.status in(1,2)";        }        $VarWhere                   = '';        if(@$ArrWhere[0]<>'') {            $VarWhere               = implode(" and ",$ArrWhere) ." AND d.companyid = ".$ArrUserLoggedInfo['companyid'];        }        $VarSelectDyeing            = "SELECT count(1) as trec  FROM ".KN_MASTER_DYEING_TYPE." AS d INNER JOIN ".KN_USERS." AS u ON d.updatedby = u.id WHERE ".$VarWhere;        $ObjRows					= $this->db->query($VarSelectDyeing)->row();        return $ObjRows->trec;    }    function fnListDyeingType($VarTypeName='',$VarStatus='',$VarLimit = 10, $offset = 0,$VarSortBy,$VarSortOrder,$VarAlphaFilter=''){        $ArrUserLoggedInfo = fnGetUserLoggedInfo('1');        $VarSortOrder				= ($VarSortOrder=='desc')? 'desc' : 'asc';        $VarSortCols				= array("1"=>'d.dyeingname','2'=>'d.status','3'=>'u.contactname','4'=>'d.dateupdated');        $VarSortBy					= (in_array($VarSortBy,$VarSortCols)) ? $VarSortBy : 'd.dateupdated';        $VarLimitInfo				= $VarLimit;        if($offset>=1) {$VarLimitInfo	 = $offset.",".$VarLimit;}        $ArrWhere                   = array();        if($VarTypeName<>'') {            $ArrWhere[]             = "d.dyeingname like '%".$VarTypeName."%'";        }        if($VarAlphaFilter <> '') {            $ArrWhere[]             = "d.dyeingname like '".$VarAlphaFilter."%'";        }        if($VarStatus<>'') {            $ArrWhere[]             = "d.status=".$VarStatus;        } else {            $ArrWhere[]             = "d.status in(1,2)";        }        $VarWhere                   = '';        if(@$ArrWhere[0]<>'') {            $VarWhere               = implode(" and ",$ArrWhere) ." AND d.companyid = ".$ArrUserLoggedInfo['companyid'];        }        $VarSqlAssignaTest         = "SELECT d.id,d.dyeingname,u.contactname,d.datecreated,d.dateupdated,d.status FROM ".KN_MASTER_DYEING_TYPE." AS d INNER JOIN ".KN_USERS." AS u ON d.updatedby = u.id WHERE ".$VarWhere." order by ".$VarSortBy." ".$VarSortOrder." limit ".$VarLimitInfo;        $ObjResult					= $this->db->query($VarSqlAssignaTest);        return $ObjResult;    }    function fnChangeComStat($checkboxids,$optvalue) {        $Arrids =  json_decode($checkboxids,true);        $this->db->where_in('id',$Arrids);        if($this->db->update(KN_MASTER_DYEING_TYPE,array('status' => $optvalue))) {            return true;        }        return false;    }    function fnDelDeyingType($VarTypeId='',$VarUpdatedBy='') {        if(@$VarTypeId>=1) {            $ArrUpdateData          = array('status'=>3,'dateupdated'=>date('Y-m-d H:i:s'),'updatedby'=>$VarUpdatedBy);            if($this->db->update(KN_MASTER_DYEING_TYPE,$ArrUpdateData,array('id'=>$VarTypeId))) {                $ArrResult['errcode']					    = 1;                $ArrResult['msg']							= '';                $ArrResult['id']							= $VarTypeId;                $ArrResult['eid']							= urlencode(base64_encode($VarTypeId));            } else {                $ArrResult['errcode']						= '-1';                $ArrResult['msg']							= 'Invalid Data!';            }        }        return $ArrResult;    }}